const icons={home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8',orders:'M7 3h10l3 3v15H4V3h3M8 8h8M8 12h8M8 16h5',quote:'M4 4h16v16H4zM8 8h8M8 12h6M8 16h3',box:'M3 7l9-4 9 4v11l-9 4-9-4V7zM3 7l9 5 9-5M12 12v10M7 5l9 5',cart:'M2 3h3l3 12h10l3-9H6M9 21h.01M18 21h.01',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75',warehouse:'M3 9l9-6 9 6v12H3V9zM7 21V11h10v10M7 15h10M7 18h10',wallet:'M20 8V5H4v15h17V8H4M16 12h5v5h-5v-5z',chart:'M4 3v18h17M8 16v-4M13 16V8M18 16V5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3z',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',clock:'M12 8v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',calendar:'M4 5h16v16H4V5zM8 3v4M16 3v4M4 10h16',check:'M5 12l4 4L19 6',close:'M6 6l12 12M6 18L18 6',logout:'M9 4H4v16h5M13 8l5 4-5 4M8 12h10',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',print:'M6 9V3h12v6M6 18H3V9h18v9h-3M6 14h12v7H6zM17 12h1',edit:'M15 4l5 5M4 20l4-1L21 6l-5-5L3 14l-1 8 6-3',truck:'M1 5h13v12H1zM14 9h5l3 4v4h-8M4 17a2 2 0 1 0 4 0M16 17a2 2 0 1 0 4 0',swap:'M3 7h17M16 3l4 4-4 4M21 17H4M8 13l-4 4 4 4',alert:'M12 3L2 21h20L12 3zM12 9v5M12 18h.01',gear:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3zM8 12l3 3 5-6',menu:'M4 6h16M4 12h16M4 18h16',file:'M5 3h9l5 5v13H5V3zM14 3v6h5M9 13h6M9 17h5',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2',leaf:'M20 3c-10 0-17 3-16 10 0 5 5 7 9 4s6-9 7-14zM3 21l12-12'};
const I=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const statusNames={draft:'草稿',pending:'待審核',approved:'已核准',partial:'部分交貨',completed:'已完成',converted:'已轉訂單',cancelled:'已取消',rejected:'已退回',posted:'已過帳',closed:'剩餘結案'};
const status=s=>`<span class="status ${E(s)}">${E(statusNames[s]||s)}</span>`;
const roleNames={admin:'系統管理員',manager:'營運主管',sales:'業務人員',warehouse:'倉管人員',finance:'財務人員',viewer:'唯讀檢視'};
const kindNames={quote:'報價單',order:'訂單',purchase:'採購單'};
const moveNames={adjustment:'庫存調整',transfer:'倉庫調撥',shipment:'銷貨出庫',receipt:'採購入庫',opening:'期初匯入',assembly_material:'組裝領料',assembly_finished:'組裝入庫',sales_return:'銷貨退回',purchase_return:'進貨退出',loan_out:'借出',loan_in:'借入',loan_return_in:'借出還入',loan_return_out:'借入還出'};
const S={company:sessionStorage.getItem('cheng-company')||'default',page:'dashboard',tab:'',filter:'',statusFilter:'',warehouseFilter:'',data:null,csrf:'',demo:false,docDraft:null,docDetail:null,modalKind:'',importId:null};
const btn=(label,action,id='',cls='',icon='')=>`<button type="button" class="btn ${cls}" data-action="${E(action)}" data-id="${E(id)}">${icon?I(icon):''}${E(label)}</button>`;
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>t.className='',4000);}
async function api(path,body,options={}){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-ERP-Company':S.company||'default',...(body===undefined?{}:{'Content-Type':'application/json','X-ERP-Request':'1','X-CSRF-Token':S.csrf,'Idempotency-Key':options.key||crypto.randomUUID()})},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});const result=await r.json();if(!r.ok){if(r.status===401&&S.data){S.data=null;closeModal();await init();}throw new Error(result.error||'操作未完成');}return result;}
async function refresh(){const next=await api('/api/bootstrap');if(!S.data||S.data.user.id!==next.user.id||S.data.user.role!==next.user.role){for(const k of ['opsReport','opsPick','opsEntity','rebuildPlan','opsCountImport','editEntity','v2Entity','docDraft','docDetail'])delete S[k];S.page='dashboard';S.tab='';S.filter='';S.statusFilter='';S.warehouseFilter='';S.priceRevision=(S.priceRevision||0)+1;S.previewRevision=(S.previewRevision||0)+1;clearTimeout(S.docPreviewTimer);}S.data=next;render();}
function options(rows,label,value,selected,blank='請選擇'){return `<option value="">${E(blank)}</option>`+rows.map(r=>`<option value="${E(r[value])}" ${String(r[value])===String(selected)?'selected':''}>${E(typeof label==='function'?label(r):r[label])}</option>`).join('');}
function field(label,name,value='',type='text',extra='',full=false){return `<div class="field ${full?'full':''}"><label for="f-${E(name)}">${E(label)}</label><input id="f-${E(name)}" name="${E(name)}" type="${type}" value="${E(value)}" ${extra}></div>`;}
function selectField(label,name,html,full=false){return `<div class="field ${full?'full':''}"><label for="f-${E(name)}">${E(label)}</label><select id="f-${E(name)}" name="${E(name)}">${html}</select></div>`;}
function textarea(label,name,value='',full=true){return `<div class="field ${full?'full':''}"><label for="f-${E(name)}">${E(label)}</label><textarea id="f-${E(name)}" name="${E(name)}" maxlength="4000">${E(value)}</textarea></div>`;}
function formFooter(label='儲存',form='modal-form'){return `${btn('取消','close')}<button class="btn primary" type="submit" form="${form}">${I('check')}${E(label)}</button>`;}
function modal(title,html,footer='',wide=false,sub=''){html=extendMasterForm(html);const root=$('#modal-root');root.innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><small>${E(sub)}</small><h2 id="modal-title">${E(title)}</h2></div><button type="button" class="icon-btn" data-action="close" aria-label="關閉">${I('close')}</button></header><div class="modal-body">${html}<p class="form-error" id="form-error" role="alert"></p></div>${footer?`<footer class="modal-foot">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';S.restoreFocus=document.activeElement;(root.querySelector('input:not([type=hidden]),select,textarea')||root.querySelector('button'))?.focus();}
function closeModal(){S.docDraft=null;S.docDetail=null;$('#modal-root').innerHTML='';document.body.style.overflow='';if(S.restoreFocus?.isConnected)S.restoreFocus.focus();}
function head(title,subtitle,actions='',eyebrow='WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${E(eyebrow)}</div><h1>${E(title)}</h1><p>${E(subtitle)}</p></div><div class="actions">${actions}</div></div>`;}
function table(headers,rows,empty='目前沒有資料'){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty">${I('file')}${E(empty)}</div></td></tr>`}</tbody></table></div>`;}
function panel(title,content,action='',foot=''){return `<section class="panel"><div class="panel-head"><h2>${E(title)}</h2>${action}</div>${content}${foot?`<div class="panel-foot">${foot}</div>`:''}</section>`;}
function navigate(page,tab=''){S.page=page;S.tab=tab;S.filter='';S.statusFilter='';S.warehouseFilter='';render();window.scrollTo({top:0});}
function render(){if(!S.data)return;const d=S.data,p=d.permissions,pending=d.documents.filter(x=>x.status==='pending').length;
const nav=[['dashboard','營運總覽','home',''],['orders','銷售訂單','orders',p.sell?'order':''],['quotes','報價管理','quote',p.sell?'quote':''],...(d.user.role!=='sales'?[['purchases','採購管理','cart',''],['replenishment','補貨建議','refresh',''],['inventory','庫存與倉儲','warehouse',''],['counts','庫存盤點','check','']]:[]),['products','商品資料','box',''],['partners','客戶與廠商','users',''],...(d.user.role!=='sales'?[['loans','借貨與歸還','swap','']]:[]),...(p.cost?[['finance','帳款與會計','wallet',''],['aging','帳齡分析','clock',''],['reports','營運分析','chart','']]:[]),['crm','業務追蹤','calendar','']];
nav.push(['workflows','交易作業中心','orders',''],['operations','進階作業中心','gear',''],['directory','聯絡與組織','users',''],...(p.cost?[['treasury','資金與票據','wallet','']]:[]),['capabilities','功能對標與驗收','check','']);
const title=nav.find(x=>x[0]===S.page)?.[1]||'系統管理';
$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt=""><span>成祥 ERP<small>CHENG WORKSPACE</small></span><button class="icon-btn close-mobile" data-action="menu" aria-label="關閉選單">${I('close')}</button></div><button type="button" class="company-select" data-action="workflow-company-switch"><span class="sq">${I('leaf')}</span><span class="truncate">${E(d.settings.company)}</span>${I('down')}</button><div class="nav"><div class="nav-label">日常營運　OPERATIONS</div>${nav.map(([page,label,icon])=>`<button type="button" class="${S.page===page?'active':''}" data-page="${page}">${I(icon)}${label}${page==='orders'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}<div class="nav-label">工作空間　WORKSPACE</div><button type="button" class="${S.page==='system'?'active':''}" data-page="system">${I('settings')}系統與資料管理</button><button type="button" data-action="help">${I('shield')}使用指南</button></div><div class="side-bottom"><div class="profile"><div class="avatar">${E(d.user.name.slice(0,1))}</div><div><b>${E(d.user.name)}</b><small>${E(roleNames[d.user.role])}</small></div><button class="icon-btn" data-action="logout" aria-label="登出">${I('logout')}</button></div></div></aside><header class="topbar"><button class="icon-btn menu-toggle" data-action="menu" aria-label="開啟選單">${I('menu')}</button><div class="breadcrumb">工作空間 ${I('chevron')}<b>${E(title)}</b></div><div class="top-actions"><div class="global-search">${I('search')}<input id="global-search" aria-label="全域搜尋" placeholder="搜尋單據、客戶或商品"><kbd>Ctrl K</kbd></div><span class="online"><span class="dot"></span>本機資料庫已連線</span><button class="icon-btn" data-action="refresh" aria-label="重新整理">${I('refresh')}</button></div></header><main class="workspace">${S.demo?`<div class="banner">${I('leaf')}<span><strong>示範工作空間</strong>　目前所有客戶、商品與交易均為虛構資料，可操作體驗完整流程。</span><span class="push">DEMO ENVIRONMENT</span></div>`:''}${pageContent()}<footer class="page-footer"><span>成祥 ERP · 讓每一筆營運，都有跡可循。</span><span>CORE v0.4 · TWD · ${E(d.today)}</span></footer></main>`;}
function pageContent(){switch(S.page){case'workflows':return workflowsPage();case'operations':return operationsPage();case'capabilities':return auditPage();case'treasury':return treasuryPage();case'directory':return directoryPage();case'dashboard':return dashboard();case'orders':return documentList('order');case'quotes':return documentList('quote');case'purchases':return documentList('purchase');case'products':return productsPage();case'partners':return partnersPage();case'inventory':return inventoryPage();case'counts':return countsPage();case'replenishment':return replenishmentPage();case'aging':return agingPage();case'loans':return loansPage();case'finance':return financePage();case'reports':return reportsPage();case'manufacturing':return manufacturingPage();case'crm':return crmPage();case'system':return systemPage();default:return dashboard();}}
function metric(label,value,note,icon='chart',cls=''){return `<div class="metric"><div class="metric-top">${E(label)}<span class="metric-icon">${I(icon)}</span></div><div class="metric-value">${value}</div><div class="metric-note ${cls}">${cls==='warn'?I('alert'):I('arrow')}${E(note)}</div></div>`;}
function docRow(d){return `<tr data-open="document" data-id="${d.id}"><td><span class="mono">${E(d.no)}</span><span class="mini-name">${E(d.date)}</span></td><td><span class="customer-mark">${E(d.partner_name.slice(0,1))}</span>${E(d.partner_name)}</td><td class="strong">${money(d.total)}</td><td>${status(d.status)}</td><td><span class="muted">${E(d.due_date)}</span></td><td>${I('chevron')}</td></tr>`;}
function dashboard(){const d=S.data,orders=d.documents.filter(x=>x.kind==='order'),pending=orders.filter(x=>x.status==='pending'),active=orders.filter(x=>['approved','partial'].includes(x.status)),low=d.products.filter(p=>sum(d.stocks.filter(s=>s.product_id===p.id),s=>s.qty-s.reserved)<p.safety_qty),ar=[...(d.open_items||[]),...(d.opening_items||[])].filter(x=>x.kind==='receivable'),outstanding=sum(ar,x=>x.amount-x.paid),sales=sum((d.sales_report||[]).filter(x=>x.month===d.today.slice(0,7)),x=>x.revenue),orderAmt=sum(orders.filter(x=>!['draft','cancelled','rejected'].includes(x.status)),x=>x.total);
const quick=`<div class="quick-grid">${[['order','新建訂單','orders'],['quote','建立報價','quote'],['stock','查看庫存','warehouse'],['customer','新增客戶','users']].map(([a,l,i])=>`<button class="quick" data-action="quick" data-id="${a}">${I(i)}${l}</button>`).join('')}</div>`;
const tasks=`<div class="tasks"><div class="task"><span class="task-bullet"></span><div><b>待核准的銷售訂單</b><p>確認交易條件後即可預留庫存</p></div><span class="number">${pending.length}</span></div><div class="task"><span class="task-bullet green"></span><div><b>等待出貨</b><p>已核准、尚未完成交貨</p></div><span class="number">${active.length}</span></div><div class="task"><span class="task-bullet"></span><div><b>低於安全庫存</b><p>依所有倉庫可用量彙總</p></div><span class="number">${low.length}</span></div></div>`;
const recent=orders.slice(0,5);const report=d.sales_report||[];const grouped=Object.entries(report.reduce((m,x)=>(m[x.partner_name]=(m[x.partner_name]||0)+x.revenue,m),{})).sort((a,b)=>b[1]-a[1]).slice(0,4);const max=Math.max(...grouped.map(x=>x[1]),1);
const inventoryRows=low.slice(0,4).map(p=>`<tr><td>${E(p.name)}<span class="mini-name mono">${E(p.sku)}</span></td><td class="danger-text">${Q(sum(d.stocks.filter(s=>s.product_id===p.id),s=>s.qty-s.reserved))} ${E(p.unit)}</td><td class="muted">${Q(p.safety_qty)} ${E(p.unit)}</td></tr>`);
const customerChart=grouped.length?`<div class="bar-list">${grouped.map(([n,v])=>`<div class="bar-item"><span class="truncate">${E(n)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,v/max*100)}%"></div></div><span class="text-right mono">${money(v)}</span></div>`).join('')}</div>`:'<div class="empty">完成銷貨後，這裡會呈現客戶銷售資料。</div>';
return head('每一筆營運，都在掌握之中。','歡迎回來，'+d.user.name+'。一起看看今天的工作進度。',`<span class="date-chip">${I('calendar')}${E(d.today.replaceAll('-',' / '))}</span>${d.permissions.sell?btn('新建訂單','new-doc','order','primary','plus'):''}`,'OVERVIEW / 營運總覽')+
`<div class="cards">${metric(d.permissions.cost?'本月銷貨淨額':'已確認訂單金額',money(d.permissions.cost?sales:orderAmt),d.permissions.cost?'依實際出貨，扣除退貨':'已送審及核准訂單合計','chart','good')}${metric('待處理訂單',`${pending.length+active.length}<span class="unit">筆</span>`,`${pending.length} 筆待審核 · ${active.length} 筆待交貨`,'orders')}${metric('庫存預警',`${low.length}<span class="unit">項</span>`,'可用量低於設定的安全庫存','box',low.length?'warn':'good')}${metric(d.permissions.cost?'應收帳款餘額':'負責客戶',d.permissions.cost?money(outstanding):`${d.partners.length}<span class="unit">家</span>`,d.permissions.cost?`${ar.filter(x=>x.amount>x.paid).length} 筆帳款待沖銷`:'客戶歷史與報價即時查詢','wallet')}</div>`+
`<div class="grid-main">${panel('近期銷售訂單',table(['訂單編號','客戶名稱','金額 TWD','處理狀態','預定交期',''],recent.map(docRow)),`<button class="btn ghost" data-page="orders">查看全部 ${I('arrow')}</button>`,`<span>共 ${orders.length} 筆訂單 · 最近建立優先</span><span>ORDER MANAGEMENT</span>`)}<section class="panel"><div class="panel-head"><h2>快速作業</h2><small>QUICK ACTIONS</small></div>${quick}<hr class="divider"><div class="panel-head"><h2>今日待辦</h2><small>${pending.length+active.length} 筆</small></div>${tasks}</section></div>`+
`<div class="bottom-grid">${panel('客戶銷售概況',customerChart,'<span class="pill">累計銷貨淨額</span>')}${panel('需要關注的庫存',table(['商品','可用數量','安全庫存'],inventoryRows),`<button class="btn ghost" data-page="inventory">前往庫存 ${I('arrow')}</button>`)}</div>`;}
function listFilters(showStatus=false,showWarehouse=false){return `<div class="filters"><input id="list-search" data-filter="text" aria-label="搜尋列表" value="${E(S.filter)}" placeholder="搜尋代號、名稱或單號…">${showStatus?`<select data-filter="status" aria-label="狀態篩選"><option value="">所有狀態</option>${Object.entries(statusNames).map(([k,v])=>`<option value="${k}" ${S.statusFilter===k?'selected':''}>${v}</option>`).join('')}</select>`:''}${showWarehouse?`<select data-filter="warehouse" aria-label="倉庫篩選">${options(S.data.warehouses,'name','id',S.warehouseFilter,'所有倉庫')}</select>`:''}<span class="right muted" id="row-count"></span></div>`;}
function matches(...values){return values.join(' ').toLowerCase().includes(S.filter.toLowerCase());}
function documentList(kind){const d=S.data,rows=d.documents.filter(x=>x.kind===kind&&matches(x.no,x.partner_name,x.owner_name)&&(!S.statusFilter||x.status===S.statusFilter));const titles={order:['銷售訂單','從接單到交貨，一張訂單串起完整流程。'],quote:['報價管理','掌握每一次報價，成交後直接轉為訂單。'],purchase:['採購管理','追蹤供應商採購、分批到貨與應付帳款。']};return head(...titles[kind],`${btn('匯出','export','documents','','download')}${d.permissions[kind==='purchase'?'buy':'sell']?btn('新增'+kindNames[kind],'new-doc',kind,'primary','plus'):''}`,kind.toUpperCase()+' MANAGEMENT')+`<div class="cards">${metric('全部'+kindNames[kind],`${d.documents.filter(x=>x.kind===kind).length}<span class="unit">筆</span>`,'包含所有狀態','orders')}${metric('待審核',`${d.documents.filter(x=>x.kind===kind&&x.status==='pending').length}<span class="unit">筆</span>`,'待主管確認','clock')}${metric(kind==='quote'?'已核准報價':'待完成交貨',`${d.documents.filter(x=>x.kind===kind&&['approved','partial'].includes(x.status)).length}<span class="unit">筆</span>`,kind==='quote'?'可轉為銷售訂單':'可分批執行出入庫','truck')}${metric('列表金額',money(sum(rows,x=>x.total)),'依目前篩選範圍','wallet')}</div><section class="panel">${listFilters(true)}${table(['單據編號','往來對象','金額 TWD','狀態','預定日期',''],rows.map(docRow))}<div class="panel-foot">${rows.length} 筆結果 · 最多顯示最新 2,000 筆單據<span>點選單據查看明細與後續作業</span></div></section>`;}
function productsPage(){const d=S.data,rows=d.products.filter(p=>matches(p.sku,p.name,p.spec,p.category,p.barcode));return head('商品資料','集中管理品號、規格、售價與客戶專屬價格。',`${btn('匯出','export','products','','download')}${d.permissions.masters?btn('新增商品','edit-product','','primary','plus'):''}`,'PRODUCT CATALOG')+`<section class="panel">${listFilters()}${table(['品號 / 商品名稱','類別','規格','標準售價',...(d.permissions.cost?['參考成本']:[]),'現有 / 可用庫存',''],rows.map(p=>{const stock=d.stocks.filter(s=>s.product_id===p.id),q=sum(stock,s=>s.qty),available=sum(stock,s=>s.qty-s.reserved);return `<tr><td><span class="mono muted">${E(p.sku)}</span><div class="strong">${E(p.name)}</div></td><td><span class="tag">${E(p.category||'未分類')}</span></td><td class="muted">${E(p.spec)}</td><td>${money(p.price)}</td>${d.permissions.cost?`<td>${money(p.cost)}</td>`:''}<td class="${available<p.safety_qty?'danger-text':''}">${Q(q)} / ${Q(available)} ${E(p.unit)}</td><td>${btn('查看','product-info',p.id,'small', 'search')}${d.permissions.masters?btn('編輯','edit-product',p.id,'small','edit'):''}</td></tr>`;}))}<div class="panel-foot">${rows.length} 個商品<span>數量支援 3 位小數 · 金額支援 2 位小數</span></div></section>`;}
function partnersPage(){
 const d=S.data,rows=d.partners.filter(p=>matches(p.code,p.name,p.contact,p.phone));
 const content=rows.map(p=>`<tr><td><span class="mono muted">${E(p.code)}</span><div class="strong">${E(p.name)}</div></td><td><span class="tag">${{customer:'客戶',supplier:'供應商',both:'客戶暨供應商'}[p.kind]}</span></td><td>${E(p.contact||'—')}</td><td class="mono">${E(p.phone||'—')}</td><td>出入庫日起 ${p.payment_days} 天</td><td>${E(p.owner_name||'共用')}</td><td>${btn('資料','partner-info',p.id,'small','search')}${d.permissions.partners?btn('編輯','edit-partner',p.id,'small','edit'):''}</td></tr>`);
 return head('客戶與廠商','交易資料、聯絡紀錄與合作條件，集中於一處。',`${btn('匯出','export','partners','','download')}${d.permissions.partners?btn('新增往來對象','edit-partner','','primary','plus'):''}`,'RELATIONSHIPS')+`<section class="panel">${listFilters()}${table(['代號 / 名稱','類型','聯絡人','電話','付款條件','負責人',''],content)}<div class="panel-foot">${rows.length} 家往來對象<span>業務依負責客戶範圍存取</span></div></section>`;
}
function tabBar(tabs,current){return `<div class="subnav">${tabs.map(([k,n])=>`<button class="${current===k?'active':''}" data-tab="${k}">${E(n)}</button>`).join('')}</div>`;}
function inventoryPage(){const d=S.data,tab=S.tab||'stocks',stocks=d.stocks.filter(s=>matches(s.sku,s.name)&&(!S.warehouseFilter||s.warehouse_id===Number(S.warehouseFilter))),moves=(d.moves||[]).filter(s=>matches(s.no,s.sku,s.name,s.reference)&&(!S.warehouseFilter||s.warehouse_id===Number(S.warehouseFilter)));return head('庫存與倉儲','掌握實體庫存、訂單預留與每一次進出異動。',d.permissions.stock?`${btn('倉庫調撥','stock-form','transfer','','swap')}${d.permissions.approve?btn('庫存調整','stock-form','adjustment','primary','plus'):''}`:'','INVENTORY & WAREHOUSE')+`<div class="cards">${metric('現有庫存總量',Q(sum(d.stocks,s=>s.qty)),'跨品項計數，請留意不同單位','box')}${metric('訂單預留量',Q(sum(d.stocks,s=>s.reserved)),'已核准、尚未出貨','orders')}${metric('啟用倉庫',`${d.warehouses.length}<span class="unit">座</span>`,'各倉數量獨立管理','warehouse')}${metric(d.permissions.cost?'存貨帳面價值':'本頁庫存品項',d.permissions.cost?money(sum(d.stocks,s=>s.value)):`${d.stocks.length}`,'依移動加權平均成本','wallet')}</div>${tabBar([['stocks','現有庫存'],['moves','庫存流水'],['fulfilments','出入庫與退貨'],['warehouses','倉庫資料']],tab)}<section class="panel">${['stocks','moves'].includes(tab)?listFilters(false,true):''}${tab==='stocks'?table(['品號 / 商品','倉庫','現有庫存','預留量','可用庫存','安全存量',...(d.permissions.cost?['帳面價值']:[])],stocks.map(s=>`<tr><td><span class="mono muted">${E(s.sku)}</span><div>${E(s.name)}</div></td><td>${E(s.warehouse_name)}</td><td>${Q(s.qty)} ${E(s.unit)}</td><td>${Q(s.reserved)}</td><td class="strong">${Q(s.qty-s.reserved)}</td><td class="muted">${Q(s.safety_qty)}（全倉）</td>${d.permissions.cost?`<td>${money(s.value)}</td>`:''}</tr>`)):tab==='moves'?table(['流水單號','異動類型','品號 / 商品','倉庫','增減數量',...(d.permissions.cost?['成本增減']:[]),'來源 / 時間'],moves.map(m=>`<tr><td class="mono">${E(m.no)}</td><td>${E(moveNames[m.kind]||m.kind)}</td><td>${E(m.name)}<span class="mini-name mono">${E(m.sku)}</span></td><td>${E(m.warehouse_name)}</td><td class="${m.qty<0?'danger-text':'strong'}">${m.qty>0?'+':''}${Q(m.qty)}</td>${d.permissions.cost?`<td>${money(m.value)}</td>`:''}<td><span class="mono">${E(m.reference)}</span><span class="mini-name">${E(m.created_at.slice(0,16).replace('T',' '))} UTC</span></td></tr>`)):tab==='fulfilments'?table(['出入庫單號','類型','原始單據','往來對象','金額','作業'],(d.fulfilments||[]).map(f=>`<tr><td class="mono">${E(f.no)}</td><td>${f.kind==='shipment'?'銷貨出庫':'採購入庫'}</td><td class="mono">${E(f.document_no)}</td><td>${E(f.partner_name)}</td><td>${money(f.total)}</td><td>${d.permissions.approve?btn('退貨','return-form',f.id,'small','swap'):'—'}</td></tr>`)):table(['倉庫代號','倉庫名稱','狀態'],d.warehouses.map(w=>`<tr><td class="mono">${E(w.code)}</td><td>${E(w.name)}</td><td><span class="tag">啟用中</span></td></tr>`))}<div class="panel-foot"><span>過帳流水保留原始紀錄 · 不直接刪改</span><div class="actions">${tab==='warehouses'&&d.permissions.masters?btn('新增倉庫','warehouse-form','','small','plus'):''}${['stocks','moves'].includes(tab)?btn('匯出 CSV','export',tab,'small','download'):''}</div></div></section>${tab==='fulfilments'&&d.returns?.length?`<div style="margin-top:20px">${panel('退貨紀錄',table(['退貨單號','原出入庫單','金額','原因'],d.returns.map(r=>`<tr><td class="mono">${E(r.no)}</td><td class="mono">${E(r.source_no)}</td><td>${money(r.total)}</td><td>${E(r.reason)}</td></tr>`)))}</div>`:''}`;}
function financePage(){const d=S.data,tab=S.tab||'receivable',allItems=[...d.open_items.filter(o=>!o.billing_batch_id),...(d.monthly_bills||[]).map(b=>({...b,monthly:true,source_no:b.no,partner_name:b.partner.name})),...(d.opening_items||[]).map(o=>({...o,opening:true,source_no:o.no,document_no:o.reference}))],ar=allItems.filter(x=>x.kind==='receivable'),ap=allItems.filter(x=>x.kind==='payable'),items=(tab==='payable'?ap:ar).filter(x=>matches(x.partner_name,x.source_no,x.document_no));const debit=sum(d.accounts,x=>x.debit),credit=sum(d.accounts,x=>x.credit);return head('帳款與會計','出入庫自動立帳，收付款與總帳同步留存。',`${btn('匯出帳款','export','open_items','','download')}${d.permissions.finance?btn('新增一般傳票','journal-form','','primary','plus'):''}`,'FINANCE & ACCOUNTING')+`<div class="cards">${metric('應收未結餘額',money(sum(ar,x=>x.amount-x.paid)),'銷貨應收扣除收款與退貨','wallet')}${metric('應付未結餘額',money(sum(ap,x=>x.amount-x.paid)),'進貨應付扣除付款與退貨','cart')}${metric('逾期應收',money(sum(ar.filter(x=>x.due_date<d.today),x=>x.amount-x.paid)),'到期日早於今天的未結金額','clock','warn')}${metric('總帳借貸差額',money(Math.abs(debit-credit)),'應維持為 0','shield',debit===credit?'good':'warn')}</div>${tabBar([['receivable','應收帳款'],['payable','應付帳款'],['payments','收付款紀錄'],['journals','會計傳票'],['trial','試算表']],tab)}<section class="panel">${['receivable','payable'].includes(tab)?listFilters():''}${['receivable','payable'].includes(tab)?table(['往來對象','來源單號','到期日','帳款金額','已沖帳','未結餘額',''],items.map(o=>`<tr><td>${E(o.partner_name)}</td><td class="mono">${E(o.source_no)}<span class="mini-name">${E(o.document_no)}</span></td><td class="${o.due_date<d.today&&o.amount>o.paid?'danger-text':''}">${E(o.due_date)}</td><td>${money(o.amount)}</td><td>${money(o.paid)}</td><td class="strong">${money(o.amount-o.paid)}</td><td>${o.amount>o.paid&&d.permissions.finance?(o.monthly?btn('月結收付款','workflow-month-pay',o.id,'small'):o.opening?btn('期初沖帳','v2-form','opening-pay:'+o.id,'small'):btn(tab==='payable'?'付款':'收款','payment-form',o.id,'small','wallet')):status('completed')}${!o.opening&&!o.monthly&&d.permissions.finance?btn('折讓','v2-form','allowance:'+o.id,'small'):''}</td></tr>`)):tab==='payments'?table(['收付款單號','往來對象','類型','日期','金額','備註'],d.payments.map(p=>`<tr><td class="mono">${E(p.no)}</td><td>${E(p.partner_name)}</td><td>${p.kind==='receivable'?'收款':'付款'}</td><td>${E(p.date)}</td><td>${money(p.amount)}</td><td>${E(p.reference)}</td></tr>`)):tab==='journals'?table(['傳票號碼','日期','摘要','來源','借貸金額',''],d.journals.map(j=>`<tr><td class="mono">${E(j.no)}</td><td>${E(j.date)}</td><td>${E(j.memo)}</td><td class="mono">${E(j.reference)}</td><td>${money(j.amount)}</td><td>${btn('明細','journal-detail',j.id,'small','search')}</td></tr>`)):table(['科目','名稱','類別','借方累計','貸方累計','借方淨額'],d.accounts.map(a=>`<tr><td class="mono">${E(a.code)}</td><td>${E(a.name)}</td><td class="muted">${E({asset:'資產',liability:'負債',equity:'權益',revenue:'收入',expense:'費用'}[a.kind])}</td><td>${money(a.debit)}</td><td>${money(a.credit)}</td><td class="strong">${money(a.debit-a.credit)}</td></tr>`))}<div class="panel-foot">單一公司 · TWD · 管理帳務<span>正式報稅與電子發票介接尚未啟用</span></div></section>`;}
function reportsPage(){const d=S.data,rows=d.sales_report,revenue=sum(rows,x=>x.revenue),cost=sum(rows,x=>x.cost),stocks=sum(d.stocks,x=>x.value);const grouped=Object.entries(rows.reduce((m,x)=>(m[x.owner_name]??={revenue:0,cost:0},m[x.owner_name].revenue+=x.revenue,m[x.owner_name].cost+=x.cost,m),{}));return head('營運分析','讓訂單、銷售與庫存資料，轉化成清楚的營運視角。',btn('匯出訂單','export','documents','','download'),'BUSINESS INSIGHTS')+`<div class="cards">${metric('累計銷貨淨額',money(revenue),'依已出貨資料扣除退貨','chart')}${metric('銷貨成本',money(cost),'出庫時的實際存貨成本','box')}${metric('銷貨毛利',money(revenue-cost),revenue?'毛利率 '+((revenue-cost)/revenue*100).toFixed(1)+'%':'尚無銷貨資料','chart','good')}${metric('存貨帳面金額',money(stocks),'各倉存貨金額合計','warehouse')}</div><div class="bottom-grid">${panel('業務銷售分析',table(['業務','銷貨淨額','毛利'],grouped.map(([n,x])=>`<tr><td>${E(n)}</td><td>${money(x.revenue)}</td><td class="strong">${money(x.revenue-x.cost)}</td></tr>`)))}${panel('月份 × 客戶銷售明細',table(['月份','客戶','銷貨淨額','毛利'],rows.map(x=>`<tr><td>${E(x.month)}</td><td>${E(x.partner_name)}</td><td>${money(x.revenue)}</td><td>${money(x.revenue-x.cost)}</td></tr>`)))}</div><div class="alert" style="margin-top:20px">退貨於本版分析歸屬原銷貨月份；財務期間認列請查會計傳票。庫存數量跨商品合計僅作作業計數，不代表可比較的實體單位。</div>`;}
function manufacturingPage(){const d=S.data,tab=S.tab||'work';return head('組裝與借用','以 BOM 記錄材料，完成組裝自動領料入庫。',d.permissions.stock?`${btn('建立借用','loan-form','','','swap')}${btn('新增組裝工單','work-form','','primary','plus')}`:'','ASSEMBLY & LOANS')+tabBar([['work','組裝工單'],['bom','組成品 BOM'],['loans','借出入紀錄']],tab)+`<section class="panel">${tab==='work'?table(['工單號碼','成品','倉庫','數量','狀態',...(d.permissions.cost?['完工成本']:[]),''],(d.work_orders||[]).map(w=>`<tr><td class="mono">${E(w.no)}</td><td>${E(w.product_name)}</td><td>${E(w.warehouse_name)}</td><td>${Q(w.qty)} ${E(w.unit)}</td><td>${status(w.status)}</td>${d.permissions.cost?`<td>${money(w.cost)}</td>`:''}<td>${w.status==='draft'&&d.permissions.stock?btn('領料並完工','complete-work',w.id,'small','check'):''}</td></tr>`)):tab==='bom'?table(['組成品','BOM 名稱','材料','版本',''],(d.boms||[]).map(b=>`<tr><td>${E(b.product_name)}<span class="mini-name mono">${E(b.sku)}</span></td><td>${E(b.name)}</td><td>${b.lines.map(l=>`${E(l.name)} × ${Q(l.qty)}`).join('<br>')}</td><td>v${b.version}</td><td>${d.permissions.masters?btn('編輯','bom-form',b.id,'small','edit'):''}</td></tr>`)):table(['借用單號','類型 / 對象','商品','借用 / 未還數量','應還日期',''],(d.loans||[]).map(l=>`<tr><td class="mono">${E(l.no)}</td><td>${l.kind==='out'?'借出':'借入'}<span class="mini-name">${E(l.partner_name)}</span></td><td>${E(l.product_name)}</td><td>${Q(l.qty)} / <b>${Q(l.qty-l.returned_qty)}</b> ${E(l.unit)}</td><td>${E(l.due_date)}</td><td>${l.qty>l.returned_qty&&d.permissions.stock?btn('歸還','loan-return',l.id,'small','swap'):status('completed')}</td></tr>`))}<div class="panel-foot">單階 BOM · 工單一次完工 · 材料成本轉入成品${tab==='bom'&&d.permissions.masters?btn('新增 BOM','bom-form','','small','plus'):''}</div></section>`;}
function crmPage(){const d=S.data,rows=d.activities.filter(a=>matches(a.partner_name,a.title,a.notes));return head('業務追蹤','把客戶溝通、下次聯繫與訂單資料放在一起。',d.permissions.partners?btn('新增聯繫紀錄','activity-form','','primary','plus'):'','SALES RELATIONSHIP')+`<section class="panel">${listFilters()}${table(['往來客戶','追蹤主題','聯繫內容','下次聯繫','負責人'],rows.map(a=>`<tr><td>${E(a.partner_name)}</td><td class="strong">${E(a.title)}</td><td style="white-space:pre-wrap;max-width:350px">${E(a.notes)}</td><td class="${a.next_date&&a.next_date<=d.today?'danger-text':''}">${E(a.next_date||'—')}</td><td>${E(a.owner_name)}</td></tr>`))}<div class="panel-foot">${rows.length} 筆聯繫紀錄<span>業務僅能查看本人紀錄</span></div></section>`;}
function systemPage(){const d=S.data,admin=d.user.role==='admin',tab=S.tab||'overview';return head('系統與資料管理','管理公司設定、權限、匯入與資料備份。',admin?btn('下載資料庫備份','backup','','primary','download'):'','SYSTEM & DATA')+tabBar([['overview','系統概況'],...(admin?[['company','公司設定'],['users','使用者權限'],['import','舊資料匯入']]:[]),...(d.audit?[['audit','操作紀錄']]:[])],tab)+(tab==='overview'?`<div class="info-grid"><div class="info-card"><h3>資料庫與一致性檢查</h3><p>庫存、帳款與會計總帳共用交易機制。可檢查庫存流水、訂單預留、借貸平衡與控制科目。</p>${admin?btn('執行一致性檢查','integrity','','','shield'):''}<div id="integrity-result"></div></div><div class="info-card"><h3>目前工作空間</h3><p>公司：${E(d.settings.company)}<br>資料模式：${S.demo?'獨立虛構示範資料':'公司正式資料庫（尚需上線驗收）'}<br>幣別：TWD · 時區：Asia/Taipei<br>已結帳至：${E(d.settings.closed_until||'尚未設定')}<br>使用者角色：${E(roleNames[d.user.role])}</p>${btn('變更我的密碼','password-form','','','shield')}</div><div class="info-card"><h3>資料轉換流程</h3><p>由舊系統匯出 CSV → 依模板整理 → 預覽檢核 → 確認匯入 → 期初對帳。</p><p>已支援商品、客戶／廠商與期初庫存匯入。歷史訂單、完整會計開帳需另行映射；期初未結帳款可由資金與票據建立，不會直接修改舊系統。</p></div><div class="info-card"><h3>功能範圍與上線準備</h3><p>目前提供核心試行版。電子發票、薪資、進出口、多公司合併、批號效期與完整製造排程仍待建置。完整功能盤點與研究已存放於專案 docs 目錄。</p>${btn('查看使用指南','help','','','file')}</div></div>`:tab==='company'?`<div class="info-card"><h3>公司基本資料</h3><form id="company-form" data-form="company"><div class="form-grid">${field('公司名稱','company',d.settings.company,'text','required maxlength="100"')}${field('統一編號','tax_id',d.settings.tax_id,'text','maxlength="20"')}${field('聯絡電話','phone',d.settings.phone)}${field('地址','address',d.settings.address)}${field('預設稅率（基點，500 = 5%）','tax_bp',d.settings.tax_bp,'number','min="0" max="10000" step="1" required')}${field('結帳截止日（設定後不可回退）','closed_until',d.settings.closed_until,'date')}</div><p class="warning-note">結帳日當天及以前禁止新增庫存與帳務過帳。稅率設定為可調整預設值，實際交易需由公司確認。</p><p class="form-error" id="page-error"></p><button class="btn primary" type="submit">儲存設定</button></form></div>`:tab==='users'?`<section class="panel">${table(['帳號','姓名','角色','狀態',''],d.users.map(u=>`<tr><td class="mono">${E(u.username)}</td><td>${E(u.name)}</td><td>${E(roleNames[u.role])}</td><td>${u.active?'啟用':'停用'}</td><td>${btn('編輯','user-form',u.id,'small','edit')}</td></tr>`))}<div class="panel-foot">變更使用者權限後會登出該使用者的所有連線。${btn('新增使用者','user-form','','small','plus')}</div></section>`:tab==='audit'?`<section class="panel">${table(['時間 UTC','操作者','動作','資料類型 / ID','內容'],d.audit.map(a=>`<tr><td class="mono">${E(a.created_at.slice(0,19).replace('T',' '))}</td><td>${E(a.actor_name||'系統')}</td><td>${E(a.action)}</td><td>${E(a.entity)} / ${E(a.entity_id)}</td><td style="white-space:pre-wrap;max-width:400px;font-size:10px">${E(a.detail)}</td></tr>`))}</section>`:`<div class="info-card"><h3>CSV 匯入 · 先預覽，再一次寫入</h3><p>請先備份。支援 UTF-8 CSV、雙引號與欄位內換行。代號重複會擋下整批；匯入只新增資料。</p><form id="import-form" data-form="import-preview"><div class="form-grid">${selectField('匯入類型','kind','<option value="products">商品基本資料</option><option value="partners">客戶／供應商</option><option value="opening_stock">期初庫存</option>')}<div class="field"><label for="import-file">CSV 檔案（最多 2,000 列）</label><input id="import-file" type="file" accept=".csv,text/csv" required></div></div><p class="hint">商品：sku,name,spec,category,unit,barcode,price,cost,safety_qty<br>往來：code,name,kind,contact,phone,email,tax_id,address,payment_days,credit_limit<br>期初：sku,warehouse_code,qty,unit_cost<br>金額與數量使用一般數字，例如 480.00、12.500。</p><div class="actions">${btn('下載範例模板','import-template','','','download')}<button class="btn primary" type="submit">預覽與檢核</button></div><p class="form-error" id="page-error"></p></form><div id="import-result"></div></div>`);}

function countsPage(){const d=S.data;return head('庫存盤點','建立帳面快照、記錄實盤數量，再由主管過帳差異。',d.permissions.stock?btn('建立盤點單','count-create','','primary','plus'):'','PHYSICAL INVENTORY')+`<div class="alert">盤點期間請停止該倉出入庫。若快照建立後有任何庫存流水，系統將阻擋差異過帳，避免以過期數量覆蓋庫存。</div>`+panel('盤點單據',table(['盤點單號','倉庫','狀態','建立日期','備註',''],(d.inventory_counts||[]).map(c=>`<tr><td class="mono">${E(c.no)}</td><td>${E(c.warehouse_name)}</td><td>${status(c.status)}</td><td>${E(c.created_at.slice(0,10))}</td><td>${E(c.notes)}</td><td>${btn('開啟','count-open',c.id,'small','search')}</td></tr>`)),'','最多顯示最近 500 張 · 每倉每張最多 2,000 項啟用商品');}
function replenishmentPage(){const d=S.data,rows=(d.replenishment||[]).filter(r=>matches(r.sku,r.name,r.supplier_name));return head('補貨建議','以全倉安全存量、可用庫存與已核准在途採購估算。','','REPLENISHMENT')+`<div class="alert">建議量 = max（安全存量 − 全倉可用量 − 已核准採購未交量，0）。未核准採購不列入在途；此為人工決策參考，不會自動送單。</div><section class="panel">${listFilters()}${table(['商品','主要供應商','全倉可用','採購在途','安全存量','建議補貨',''],rows.map(r=>`<tr><td>${E(r.name)}<span class="mini-name mono">${E(r.sku)}</span></td><td>${E(r.supplier_name||'未指定')}</td><td>${Q(r.available_qty)}</td><td>${Q(r.incoming_qty)}</td><td>${Q(r.safety_qty)}</td><td class="strong">${Q(r.suggested_qty)} ${E(r.unit)}</td><td>${r.suggested_qty>0&&d.permissions.buy?btn('建立採購草稿','replenish-draft',r.product_id,'small','cart'):''}</td></tr>`))}</section>`;}
function agingPage(){const d=S.data,kind=S.tab||'receivable',grouped=new Map();for(const o of [...d.open_items,...(d.opening_items||[])].filter(x=>x.kind===kind&&x.amount>x.paid)){let r=grouped.get(o.partner_id);if(!r){r={name:o.partner_name,buckets:[0,0,0,0,0],total:0};grouped.set(o.partner_id,r);}const days=Math.floor((Date.parse(d.today+'T00:00:00Z')-Date.parse(o.due_date+'T00:00:00Z'))/86400000),i=days<=0?0:days<=30?1:days<=60?2:days<=90?3:4,amount=o.amount-o.paid;r.buckets[i]+=amount;r.total+=amount;}const rows=[...grouped.values()].filter(x=>matches(x.name)),total=rows.reduce((a,r)=>a.map((v,i)=>v+r.buckets[i]),[0,0,0,0,0]);return head('帳齡分析','依到期日將未結帳款分組，協助安排催收與付款。',btn('匯出帳款','export','open_items','','download'),'AGING ANALYSIS')+tabBar([['receivable','應收帳齡'],['payable','應付帳齡']],kind)+`<section class="panel">${listFilters()}${table(['往來對象','未到期／今日到期','逾期 1–30 天','31–60 天','61–90 天','超過 90 天','未結合計'],[...rows.map(r=>`<tr><td>${E(r.name)}</td>${r.buckets.map(v=>`<td>${money(v)}</td>`).join('')}<td class="strong">${money(r.total)}</td></tr>`),`<tr><td><b>合計</b></td>${total.map(v=>`<td class="strong">${money(v)}</td>`).join('')}<td class="strong">${money(sum(rows,x=>x.total))}</td></tr>`])}<div class="panel-foot">基準日 ${E(d.today)}<span>以目前未結餘額分組，非任意歷史日重建</span></div></section>`;}
function loansPage(){const d=S.data;return head('借貨與歸還','追蹤樣品借出、借入及分次歸還，保留存貨與帳務軌跡。',d.permissions.stock?btn('新增借用單','loan-form','','primary','plus'):'','LOANS & RETURNS')+panel('借出入紀錄',table(['借用單號','類型 / 對象','商品','倉庫','借用 / 未還','應還日期',''],(d.loans||[]).map(l=>`<tr><td class="mono">${E(l.no)}</td><td>${l.kind==='out'?'借出':'借入'}<span class="mini-name">${E(l.partner_name)}</span></td><td>${E(l.product_name)}</td><td>${E(l.warehouse_name)}</td><td>${Q(l.qty)} / <b>${Q(l.qty-l.returned_qty)}</b> ${E(l.unit)}</td><td class="${l.due_date<d.today&&l.qty>l.returned_qty?'danger-text':''}">${E(l.due_date)}</td><td>${l.qty>l.returned_qty&&d.permissions.stock?btn('歸還','loan-return',l.id,'small','swap'):status('completed')}</td></tr>`)),'','借用仍需依實際歸還數量登錄；此頁不代表正式銷售。');}
async function countOpen(id){const c=await api('/api/inventory-counts/'+id),editable=c.status==='draft'&&S.data.permissions.stock;S.countDetail=c;modal('盤點單 '+c.no,`<form id="modal-form" data-form="count-save"><div class="detail-strip">${status(c.status)}<b>${E(c.warehouse_name)}</b><span class="hint">快照流水 ID：${c.snapshot_move_id} · 修訂 ${c.version}</span></div><div class="alert">實盤數量預填為帳面數量。請逐一核實後再過帳；差異將以目前帳面平均成本計價，零庫存新增則採商品參考成本。</div>${table(['品號 / 商品','帳面量','實盤量','單位'],c.lines.map(l=>`<tr><td>${E(l.name)}<span class="mini-name mono">${E(l.sku)}</span></td><td>${Q(l.expected_qty)}</td><td><input data-count-line="${l.id}" type="number" min="0" step="0.001" value="${inputQty(l.actual_qty)}" ${editable?'':'readonly'} required style="width:110px;padding:7px" aria-label="${E(l.name)}實盤數量"></td><td>${E(l.unit)}</td></tr>`))}<div class="form-grid" style="margin-top:18px">${textarea('盤點備註','notes',c.notes)}</div></form>`,`${btn('關閉','close')}${editable?`<button class="btn" type="submit" form="modal-form">儲存實盤</button>`:''}${c.status==='draft'&&S.data.permissions.approve?btn('儲存並過帳差異','count-post',c.id,'primary','check')+btn('取消盤點單','count-cancel',c.id,'danger'):''}`,true);}
async function orderPurchaseForm(id){
 const d=await api('/api/documents/'+id);S.orderPurchase=d;
 const targetIds=(S.data.document_links||[]).filter(l=>l.source_id===d.id&&l.target_status!=='cancelled').map(l=>l.target_id);
 const rows=d.lines.filter(l=>l.qty>l.done_qty).map(l=>{
  const p=S.data.products.find(p=>p.id===l.product_id),s=S.data.stocks.find(s=>s.product_id===l.product_id&&s.warehouse_id===d.warehouse_id),remaining=l.qty-l.done_qty,already=l.procured_qty||0,maximum=Math.max(0,remaining-already),ownReserved=['approved','partial'].includes(d.status)?remaining:0,available=(s?.qty||0)-(s?.reserved||0)+ownReserved,suggested=Math.min(maximum,Math.max(0,remaining-available-already));
  return `<tr data-po-line="${l.product_id}"><td>${E(l.name)}</td><td>${Q(remaining)}</td><td>${Q(already)}</td><td><input name="po_qty" type="number" min="0" max="${inputQty(maximum)}" step="0.001" value="${inputQty(suggested)}" aria-label="${E(l.name)}採購量" required style="width:100px;padding:7px"></td><td><input name="po_price" type="number" min="0" step="0.01" value="${inputMoney(p.cost)}" aria-label="${E(l.name)}採購單價" required style="width:100px;padding:7px"></td></tr>`;
 });
 modal('訂單轉採購草稿',`<form id="modal-form" data-form="order-purchase"><div class="alert">來源：${E(d.no)} · ${E(d.partner_name)}<br>依未交量填入採購數量。已有 ${targetIds.length} 張連動採購。數量依原訂單單位填寫；採購單會換算為基本單位，單價請填每基本單位價格。伺服器會檢查累計量，避免重複採買。</div><div class="form-grid">${selectField('供應商','partner_id',options(S.data.partners.filter(p=>p.kind!=='customer'),'name','id',''))}${field('預定到貨日期','due_date',d.due_date<S.data.today?S.data.today:d.due_date,'date','required')}</div><div class="section-title">本次採購明細 · 不採購的列請填 0</div>${table(['商品','原訂單未交','已連動採購','採購量（原訂單單位）','採購單價（每基本單位）TWD'],rows)}<div class="form-grid" style="margin-top:15px">${textarea('採購備註','notes','')}</div></form>`,formFooter('建立採購草稿'),true);
}
function newDoc(kind,existing){const d=S.data;if(!d.permissions[kind==='purchase'?'buy':'sell'])throw Error('沒有建立單據的權限');S.docDraft=existing?{...existing,header_discount:inputMoney(existing.header_discount),lines:existing.lines.map(l=>({...l,tax_mode:existing.calc_version<2?undefined:l.tax_mode,tax_bp:existing.calc_version<2?undefined:l.tax_bp,qty:inputQty(l.qty),price:inputMoney(l.price)}))}:{kind,partner_id:'',warehouse_id:d.warehouses[0]?.id,date:d.today,due_date:d.today,valid_until:datePlus(d.today,30),tax_mode:'exclusive',tax_bp:Number(d.settings.tax_bp||500),notes:'',shipping_address:'',lines:[{product_id:'',qty:'1',price:'0',discount_bp:10000,notes:''}]};
const x=S.docDraft;const partners=d.partners.filter(p=>p.kind===(kind==='purchase'?'supplier':'customer')||p.kind==='both');modal((existing?'編輯':'新建')+kindNames[kind],`<form id="doc-form" data-form="document"><div class="form-grid">${selectField(kind==='purchase'?'供應商':'客戶','partner_id',options(partners,p=>p.code+' · '+p.name,'id',x.partner_id))}${selectField('出入庫倉庫','warehouse_id',options(d.warehouses,'name','id',x.warehouse_id))}${field('單據日期','date',x.date,'date','required')}${field(kind==='quote'?'有效期限':'預定交期','due_date',kind==='quote'?x.valid_until:x.due_date,'date','required')}${selectField('稅額計算','tax_mode',[['exclusive','外加稅'],['inclusive','含稅價'],['none','免稅']].map(([k,n])=>`<option value="${k}" ${x.tax_mode===k?'selected':''}>${n}</option>`).join(''))}${field('稅率（基點，500 = 5%）','tax_bp',x.tax_bp,'number','min="0" max="10000" required step="1"')}${field('送貨地址','shipping_address',x.shipping_address,'text','maxlength="300"',true)}</div><div class="section-title">商品明細 <span class="hint">選客戶後會帶入專屬價格；存檔以伺服器計算為準。</span></div><div class="lines" id="doc-lines"></div><div class="actions" style="margin-top:12px">${btn('新增商品列','add-line','','small','plus')}</div><div id="doc-totals"></div><div class="form-grid" style="margin-top:20px">${textarea('備註與交易條件','notes',x.notes)}</div></form>`,formFooter('儲存草稿','doc-form'),true,existing?existing.no:'SALES WORKSPACE / 黃單與訂單');renderDocLines();}
