async function showDoc(id){const x=await api('/api/documents/'+id),p=S.data.permissions;S.docDetail=x;const canEdit=['draft','rejected'].includes(x.status)&&p[x.kind==='purchase'?'buy':'sell'];const actionList=[`<a class="btn" target="_blank" rel="noopener" href="/print/${x.id}">${I('print')}黃單／PDF</a>`];if(canEdit)actionList.push(btn('編輯草稿','edit-doc',x.id,'','edit'));if(x.status==='draft'&&p[x.kind==='purchase'?'buy':'sell'])actionList.push(btn('送出審核','doc-action','submit','primary','arrow'));if(x.status==='pending'&&p.approve){actionList.push(btn('退回','reject-doc',x.id,'danger'),btn('核准'+kindNames[x.kind],'doc-action','approve','primary','check'));}if(x.kind==='quote'&&x.status==='approved'&&p.sell)actionList.push(btn('轉為訂單','doc-action','convert','primary','arrow'));if(['order','purchase'].includes(x.kind)&&['approved','partial'].includes(x.status)&&p.approve)actionList.push(btn('結束剩餘未交','v3-form','close:'+x.id,'danger'));if(['order','purchase'].includes(x.kind)&&['approved','partial'].includes(x.status)&&p.stock)actionList.push(btn(x.kind==='order'?'執行出貨':'執行進貨','fulfil-form',x.id,'primary','truck'));if(x.kind==='order'&&['pending','approved','partial'].includes(x.status)&&p.buy)actionList.push(btn('轉採購草稿','order-purchase-form',x.id,'','cart'));if(p.approve&&!['completed','partial','converted','cancelled','closed'].includes(x.status))actionList.push(btn('取消單據','cancel-doc',x.id,'danger'));
modal(kindNames[x.kind]+'明細',`<div class="detail-strip"><span class="mono">${E(x.no)}</span>${status(x.status)}<span class="muted">修訂 ${x.version}</span></div><div class="flow"><span class="${x.status==='draft'?'current':''}">01 建立草稿</span>${I('chevron')}<span class="${x.status==='pending'?'current':''}">02 送出審核</span>${I('chevron')}<span class="${x.status==='approved'?'current':''}">03 核准${x.kind==='order'?'與預留庫存':''}</span>${I('chevron')}<span class="${['completed','partial','converted'].includes(x.status)?'current':''}">04 ${x.kind==='quote'?'轉為訂單':'交貨與立帳'}</span></div><div class="detail-data">${[['往來對象',x.partner_name],['經辦業務',x.owner_name],['倉庫',x.warehouse_name],['單據日期',x.date],['預定日期',x.kind==='quote'?x.valid_until:x.due_date],['送貨地址',x.shipping_address||'—']].map(([k,v])=>`<div><span>${E(k)}</span><b>${E(v)}</b></div>`).join('')}</div>${table(['品號 / 品名','規格','數量','單價','折數','小計','已交 / 未交 / 結案'],x.lines.map(l=>`<tr><td>${E(l.name)}<span class="mini-name mono">${E(l.sku)}</span>${l.notes?`<span class="mini-name">${E(l.notes)}</span>`:''}</td><td class="muted">${E(l.spec)}</td><td>${Q(l.qty)} ${E(l.unit)}</td><td>${money(l.price,true)}</td><td>${l.discount_bp/100}%</td><td>${money(l.amount,true)}</td><td>${Q(l.done_qty)} / ${Q(l.qty-l.done_qty-(l.closed_qty||0))} / ${Q(l.closed_qty||0)}</td></tr>`))}<div class="totals-box">${x.header_discount?`<div><span>整單價格折扣</span><b>${money(x.header_discount,true)}</b></div>`:''}<div><span>未稅小計</span><b>${money(x.net,true)}</b></div><div><span>稅額</span><b>${money(x.tax,true)}</b></div><div><span>合計 TWD</span><b>${money(x.total,true)}</b></div></div><div class="section-title">備註與交易條件</div><div class="notes">${E(x.notes||'—')}</div>${x.fulfilments.length?`<div class="section-title">交貨紀錄</div>${table(['出入庫單號','日期','金額'],x.fulfilments.map(f=>`<tr><td class="mono">${E(f.no)}</td><td>${E(f.date)}</td><td>${money(f.total)}</td></tr>`))}`:''}`,actionList.join(''),true,'DOCUMENT / 可追溯的交易流程');}

function partnerForm(id){const p=S.data.partners.find(x=>x.id===Number(id))||{kind:'customer',payment_days:30,credit_limit:0};S.editEntity=p;const sales=S.data.user.role==='sales';modal(id?'編輯往來對象':'新增往來對象',`<form id="modal-form" data-form="partner"><div class="form-grid">${field('對象代號','code',p.code,'text','required maxlength="40"')}${field('公司／客戶名稱','name',p.name,'text','required maxlength="100"')}${selectField('類型','kind',(sales?[['customer','客戶']]:[['customer','客戶'],['supplier','供應商'],['both','客戶暨供應商']]).map(([k,n])=>`<option value="${k}" ${p.kind===k?'selected':''}>${n}</option>`).join(''))}${field('聯絡人','contact',p.contact)}${field('電話','phone',p.phone)}${field('電子郵件','email',p.email,'email')}${field('統一編號','tax_id',p.tax_id)}${field('地址','address',p.address)}${!sales?field('付款天數','payment_days',p.payment_days,'number','min="0" max="365" required step="1"')+field('信用額度 TWD（0 = 不設上限）','credit_limit',inputMoney(p.credit_limit),'number','min="0" step="0.01"')+selectField('負責人','owner_id',options(S.data.owners,'name','id',p.owner_id,'共用客戶')):''}${textarea('備註','notes',p.notes)}</div></form>`,formFooter());}
function productForm(id){const p=S.data.products.find(x=>x.id===Number(id))||{unit:'個',price:0,cost:0,safety_qty:0};S.editEntity=p;modal(id?'編輯商品':'新增商品',`<form id="modal-form" data-form="product"><div class="form-grid">${field('品號','sku',p.sku,'text','required maxlength="60"')}${field('商品名稱','name',p.name,'text','required maxlength="150"')}${field('規格','spec',p.spec)}${field('商品類別','category',p.category)}${field('單位','unit',p.unit,'text','required maxlength="20"')}${field('條碼（選填）','barcode',p.barcode)}${field('標準售價 TWD','price',inputMoney(p.price),'number','min="0" step="0.01" required')}${field('參考成本 TWD','cost',inputMoney(p.cost),'number','min="0" step="0.01" required')}${field('全倉安全庫存','safety_qty',inputQty(p.safety_qty),'number','min="0" step="0.001" required')}${selectField('主要供應商','supplier_id',options(S.data.partners.filter(x=>x.kind!=='customer'),'name','id',p.supplier_id,'不指定'))}</div><p class="hint">參考成本供採購預填；實際存貨成本由入庫與移動加權平均計算。修改這裡不會重估現有庫存。</p></form>`,formFooter());}
function stockForm(kind){S.stockKind=kind;modal(kind==='transfer'?'倉庫調撥':'庫存調整',`<form id="modal-form" data-form="stock"><div class="form-grid">${selectField('商品','product_id',options(S.data.products,p=>p.sku+' · '+p.name,'id',''))}${selectField(kind==='transfer'?'來源倉庫':'倉庫',kind==='transfer'?'from_id':'warehouse_id',options(S.data.warehouses,'name','id',S.data.warehouses[0]?.id))}${kind==='transfer'?selectField('目的倉庫','to_id',options(S.data.warehouses,'name','id','')):''}${field(kind==='transfer'?'調撥數量':'調整數量（減少請填負數）','qty','1','number',`step="0.001" ${kind==='transfer'?'min="0.001"':''} required`)}${kind==='adjustment'?field('增加庫存時的單位成本 TWD','unit_cost','0','number','min="0" step="0.01" required')+textarea('調整原因（必填）','reason',''):''}</div><p class="hint">調撥不改變公司存貨總額。減少庫存使用當前移動平均成本，且不能動用其他訂單的預留量。</p></form>`,formFooter('確認過帳'));}
async function fulfilForm(id){const x=await api('/api/documents/'+id);S.fulfilDoc=x;modal(x.kind==='order'?'銷貨出庫':'採購入庫',`<form id="modal-form" data-form="fulfil"><div class="alert">${E(x.no)} · ${E(x.partner_name)}<br>過帳後會${x.kind==='order'?'扣庫存、釋放本單預留並新增應收':'增加庫存並新增應付'}，同時產生會計傳票。</div>${table(['商品','訂購量','已交量','本次數量'],x.lines.map(l=>`<tr><td>${E(l.name)}</td><td>${Q(l.qty)}</td><td>${Q(l.done_qty)}</td><td><input class="num-input" data-fulfil-line="${l.id}" type="number" min="0" max="${inputQty(l.qty-l.done_qty-(l.closed_qty||0))}" step="0.001" value="${inputQty(l.qty-l.done_qty-(l.closed_qty||0))}" aria-label="${E(l.name)}本次數量" style="width:100px;padding:8px" required></td></tr>`))}</form>`,formFooter('確認'+(x.kind==='order'?'出貨':'入庫')));}
function paymentForm(id){const x=S.data.open_items.find(x=>x.id===Number(id));S.editEntity=x;modal(x.kind==='receivable'?'客戶收款沖帳':'廠商付款沖帳',`<form id="modal-form" data-form="payment"><div class="alert">${E(x.partner_name)} · ${E(x.source_no)}<br>尚未沖帳：TWD ${money(x.amount-x.paid,true)}</div><div class="form-grid">${field('本次金額 TWD','amount',inputMoney(x.amount-x.paid),'number',`min="0.01" max="${inputMoney(x.amount-x.paid)}" step="0.01" required`)}${field('收付款日期','date',S.data.today,'date','required')}${selectField('方式','method','<option value="bank">銀行轉帳</option><option value="cash">現金</option>')}${bankSelect()}${field('匯款備註','reference','')}</div><p class="hint">此操作只記錄帳務，不會連線銀行實際匯款。</p></form>`,formFooter('確認沖帳'));}
async function returnForm(id){const f=await api('/api/fulfilments/'+id);S.returnSource=f;modal(f.kind==='shipment'?'銷貨退回':'進貨退出',`<form id="modal-form" data-form="return"><div class="alert">${E(f.no)} · ${f.kind==='shipment'?'退回增加庫存，減少應收':'退出減少庫存，減少應付'}。已收付款的部分將建立待退款；請到「資金與票據」分次登錄實際退款。</div>${table(['商品','可退數量','本次退貨量'],f.lines.map(l=>`<tr><td>${E(l.name)}</td><td>${Q(l.qty-l.returned_qty)} ${E(l.unit)}</td><td><input data-return-line="${l.id}" type="number" min="0" max="${inputQty(l.qty-l.returned_qty)}" step="0.001" value="0" style="width:110px;padding:8px" aria-label="${E(l.name)}退貨量" required></td></tr>`))}<div class="form-grid" style="margin-top:20px">${textarea('退貨原因（必填）','reason','')}</div></form>`,formFooter('確認退貨過帳'));}
function activityForm(partnerId=''){modal('新增客戶聯繫紀錄',`<form id="modal-form" data-form="activity"><div class="form-grid">${selectField('客戶','partner_id',options(S.data.partners.filter(p=>p.kind!=='supplier'),'name','id',partnerId))}${field('下次聯繫','next_date',S.data.today,'date')}${field('追蹤主題','title','','text','required maxlength="150"',true)}${textarea('聯繫內容','notes','')}</div></form>`,formFooter());}
function workForm(){modal('新增組裝工單',`<form id="modal-form" data-form="work"><div class="form-grid">${selectField('組成品（已建 BOM）','product_id',options(S.data.boms||[],'product_name','product_id',''))}${selectField('領料與入庫倉庫','warehouse_id',options(S.data.warehouses,'name','id',S.data.warehouses[0]?.id))}${field('成品數量','qty','1','number','min="0.001" step="0.001" required')}</div><p class="hint">建立時保留當前 BOM 快照。完工時一次扣除材料並增加成品；本版本尚未提供排程與分批報工。</p></form>`,formFooter('建立工單'));}
function bomForm(id){const b=(S.data.boms||[]).find(b=>b.id===Number(id))||{lines:[]};S.editEntity=b;S.bomLines=b.lines.length?b.lines.map(l=>({product_id:l.product_id,qty:inputQty(l.qty)})):[{product_id:'',qty:'1'}];modal(id?'編輯 BOM':'新增組成品 BOM',`<form id="modal-form" data-form="bom"><div class="form-grid">${selectField('成品','product_id',options(S.data.products,p=>p.sku+' · '+p.name,'id',b.product_id))}${field('BOM 名稱','name',b.name||'','text','maxlength="150"')}</div><div class="section-title">每 1 單位成品所需材料</div><div id="bom-lines" class="lines"></div><div style="margin-top:12px">${btn('新增材料','bom-add','','small','plus')}</div></form>`,formFooter(),true);renderBom();}
function collectBom(){S.bomLines=$$('#bom-lines tbody tr').map(tr=>({product_id:tr.querySelector('select').value,qty:tr.querySelector('input').value}));}
function renderBom(){$('#bom-lines').innerHTML=table(['材料','每單位用量',''],S.bomLines.map((l,i)=>`<tr><td><select aria-label="材料 ${i+1}" required>${options(S.data.products,p=>p.sku+' · '+p.name,'id',l.product_id)}</select></td><td><input type="number" min="0.001" step="0.001" value="${E(l.qty)}" aria-label="材料用量" required></td><td>${btn('移除','bom-remove',i,'small')}</td></tr>`));}
function loanForm(){modal('新增借出入紀錄',`<form id="modal-form" data-form="loan"><div class="form-grid">${selectField('類型','kind','<option value="out">借出（庫存轉為借出資產）</option><option value="in">借入（庫存與借入義務增加）</option>')}${selectField('往來對象','partner_id',options(S.data.partners,'name','id',''))}${selectField('商品','product_id',options(S.data.products,p=>p.sku+' · '+p.name,'id',''))}${selectField('倉庫','warehouse_id',options(S.data.warehouses,'name','id',S.data.warehouses[0]?.id))}${field('借用數量','qty','1','number','min="0.001" step="0.001" required')}${field('應還日期','due_date',S.data.today,'date','required')}${textarea('借用說明','notes','')}</div><p class="hint">借入使用產品參考成本。借出歸還沿用原借出成本；借入歸還的成本差額記入存貨調整損益。</p></form>`,formFooter('確認借出入過帳'));}
function userForm(id){const u=(S.data.users||[]).find(u=>u.id===Number(id))||{role:'sales',active:1};S.editEntity=u;modal(id?'編輯使用者':'新增使用者',`<form id="modal-form" data-form="user"><div class="form-grid">${id?`<div class="field"><label>帳號</label><b>${E(u.username)}</b></div>`:field('帳號','username','','text','required minlength="3" maxlength="50" autocomplete="off"')}${field('姓名','name',u.name,'text','required maxlength="80"')}${selectField('角色','role',Object.entries(roleNames).map(([k,n])=>`<option value="${k}" ${u.role===k?'selected':''}>${n}</option>`).join(''))}${selectField('狀態','active',`<option value="1" ${u.active?'selected':''}>啟用</option><option value="0" ${!u.active?'selected':''}>停用</option>`)}${field(id?'新密碼（留白保持原密碼）':'密碼（至少 12 字）','password','','password',`${id?'':'required'} minlength="12" maxlength="128" autocomplete="new-password"`,true)}</div><p class="hint">業務：自己的客戶與銷售單據。倉管：庫存與出入庫。財務：帳款與傳票。主管：核准與營運。管理員：完整系統設定。</p></form>`,formFooter());}
function journalForm(){S.journalLines=2;modal('新增一般會計傳票',`<form id="modal-form" data-form="journal"><div class="form-grid">${field('日期','date',S.data.today,'date','required')}${field('摘要','memo','','text','required maxlength="500"')}</div><div class="section-title">傳票明細</div><div class="lines" id="journal-lines"></div><div style="margin-top:12px">${btn('新增分錄列','journal-add','','small','plus')}</div><p class="hint">借貸總額必須相等。應收、應付、存貨及借用控制科目需從原始業務流程過帳。</p></form>`,formFooter('確認過帳'),true);addJournalRows(2);}
function addJournalRows(n=1){const el=$('#journal-lines');if(!el.querySelector('table'))el.innerHTML=table(['會計科目','借方 TWD','貸方 TWD'],[]);const tbody=el.querySelector('tbody');tbody.querySelector('.empty')?.closest('tr').remove();for(let i=0;i<n;i++)tbody.insertAdjacentHTML('beforeend',`<tr><td><select name="account" required>${options(S.data.accounts.filter(a=>!['1100','1105','1150','1200','1250','1400','2000','2010','2200','2300','2400','2500'].includes(a.code)&&!a.code.startsWith('1000-')),a=>a.code+' · '+a.name,'code','')}</select></td><td><input name="debit" type="number" min="0" step="0.01" value="0" required aria-label="借方金額"></td><td><input name="credit" type="number" min="0" step="0.01" value="0" required aria-label="貸方金額"></td></tr>`);}

function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;const s=text.replace(/^\uFEFF/,'');for(let i=0;i<s.length;i++){const c=s[i];if(quoted){if(c==='"'&&s[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}else if(c==='"'&&cell==='')quoted=true;else if(c===','){row.push(cell);cell='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV 的雙引號沒有關閉');row.push(cell);if(row.some(x=>x!==''))rows.push(row);if(rows.length<2)throw Error('CSV 需有欄名與至少一列資料');const headers=rows.shift().map(x=>x.trim());if(new Set(headers).size!==headers.length||headers.some(x=>!x))throw Error('CSV 欄名不得重複或空白');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error(`第 ${i+2} 列欄位數與標頭不同`);return Object.fromEntries(headers.map((h,j)=>[h,r[j]]));});}
function downloadText(name,text){const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function showPartner(id){const p=S.data.partners.find(x=>x.id===Number(id)),docs=S.data.documents.filter(x=>x.partner_id===p.id),prices=S.data.prices.filter(x=>x.partner_id===p.id);S.editEntity=p;modal(p.name,`<div class="detail-data">${[['代號',p.code],['聯絡人',p.contact],['電話',p.phone],['電子郵件',p.email],['統編',p.tax_id],['地址',p.address],['付款天數',p.payment_days],['信用額度',p.credit_limit?money(p.credit_limit):'未設上限']].map(([k,v])=>`<div><span>${E(k)}</span><b>${E(v||'—')}</b></div>`).join('')}</div><div class="section-title">近期交易單據</div>${table(['單號','種類','金額','狀態'],docs.slice(0,20).map(d=>`<tr data-open="document" data-id="${d.id}"><td class="mono">${E(d.no)}</td><td>${E(kindNames[d.kind])}</td><td>${money(d.total)}</td><td>${status(d.status)}</td></tr>`))}<div class="section-title">客戶專屬價格</div>${table(['商品','單價'],prices.map(p=>`<tr><td>${E(S.data.products.find(x=>x.id===p.product_id)?.name)}</td><td>${money(p.price,true)}</td></tr>`))}<div class="notes" style="margin-top:20px">${E(p.notes)}</div>`,`${S.data.permissions.partners?btn('新增聯繫','activity-form',p.id,'','plus'):''}${S.data.permissions.masters&&p.kind!=='supplier'?btn('設定專屬價格','price-form',p.id,'primary','wallet'):''}`,true);}
function showProduct(id){const p=S.data.products.find(p=>p.id===Number(id)),stocks=S.data.stocks.filter(s=>s.product_id===p.id);modal(p.name,`<div class="detail-data">${[['品號',p.sku],['規格',p.spec],['類別',p.category],['單位',p.unit],['條碼',p.barcode],['標準售價',money(p.price)]].map(([k,v])=>`<div><span>${E(k)}</span><b>${E(v||'—')}</b></div>`).join('')}</div>${table(['倉庫','現有','預留','可用'],stocks.map(s=>`<tr><td>${E(s.warehouse_name)}</td><td>${Q(s.qty)}</td><td>${Q(s.reserved)}</td><td class="strong">${Q(s.qty-s.reserved)}</td></tr>`))}`,btn('關閉','close'));}

document.addEventListener('click',async ev=>{
 const page=ev.target.closest('[data-page]');if(page){navigate(page.dataset.page);return;}
 const tab=ev.target.closest('[data-tab]');if(tab){S.tab=tab.dataset.tab;S.filter='';S.statusFilter='';render();return;}
 const open=ev.target.closest('[data-open]');if(open){try{await showDoc(open.dataset.id);}catch(e){toast(e.message,true);}return;}
 const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 try{
 if(a==='close'){closeModal();return;}if(a==='menu'){ $('.sidebar').classList.toggle('open');return;}
 if(a==='new-doc'){newDoc(id);return;}if(a==='edit-doc'){const d=await api('/api/documents/'+id);newDoc(d.kind,d);return;}
 if(a==='count-create'){modal('建立庫存盤點單',`<form id="modal-form" data-form="count-create"><div class="form-grid">${selectField('盤點倉庫','warehouse_id',options(S.data.warehouses,'name','id',S.data.warehouses[0]?.id))}${textarea('盤點說明','notes','')}</div><p class="hint">建立後取得該倉帳面快照，請暫停該倉庫出入庫直到差異過帳完成。</p></form>`,formFooter('建立快照'));return;}
 if(a==='count-open'){await countOpen(id);return;}
 if(a==='count-cancel'){S.countToCancel=S.countDetail;modal('取消盤點單',`<form id="modal-form" data-form="count-cancel"><p>${E(S.countToCancel.no)}</p><div class="form-grid">${textarea('取消原因（必填）','reason','')}</div></form>`,formFooter('確認取消'));return;}
 if(a==='order-purchase-form'){await orderPurchaseForm(id);return;}
 if(a==='replenish-draft'){const r=S.data.replenishment.find(r=>r.product_id===Number(id)),p=S.data.products.find(p=>p.id===r.product_id);newDoc('purchase');S.docDraft.lines=[{product_id:p.id,qty:inputQty(r.suggested_qty),price:inputMoney(p.cost),discount_bp:10000,notes:''}];if(r.supplier_id)$('#f-partner_id').value=r.supplier_id;$('#f-notes').value='安全庫存補貨建議；請確認數量與交期。';renderDocLines();return;}
 if(a==='add-line'){collectDocLines();S.docDraft.lines.push({product_id:'',qty:'1',price:'0',discount_bp:10000,notes:''});renderDocLines();return;}
 if(a==='remove-line'){collectDocLines();S.docDraft.lines.splice(Number(id),1);renderDocLines();return;}
 if(a==='edit-partner'){partnerForm(id);return;}if(a==='edit-product'){productForm(id);return;}
 if(a==='stock-form'){stockForm(id);return;}if(a==='fulfil-form'){await fulfilForm(id);return;}if(a==='payment-form'){paymentForm(id);return;}if(a==='return-form'){await returnForm(id);return;}
 if(a==='activity-form'){activityForm(id);return;}if(a==='work-form'){workForm();return;}if(a==='bom-form'){bomForm(id);return;}if(a==='loan-form'){loanForm();return;}if(a==='user-form'){userForm(id);return;}if(a==='journal-form'){journalForm();return;}if(a==='journal-add'){addJournalRows();return;}
 if(a==='bom-add'){collectBom();S.bomLines.push({product_id:'',qty:'1'});renderBom();return;}if(a==='bom-remove'){collectBom();S.bomLines.splice(Number(id),1);renderBom();return;}
 if(a==='partner-info'){await showPartner(id);return;}if(a==='product-info'){showProduct(id);return;}
 if(a==='price-form'){S.pricePartner=Number(id);modal('設定客戶專屬價格',`<form id="modal-form" data-form="price"><div class="form-grid">${selectField('商品','product_id',options(S.data.products,p=>p.sku+' · '+p.name,'id',''))}${field('專屬售價 TWD','price','0','number','min="0" step="0.01" required')}</div></form>`,formFooter());return;}
 if(a==='warehouse-form'){modal('新增倉庫',`<form id="modal-form" data-form="warehouse"><div class="form-grid">${field('倉庫代號','code','','text','required maxlength="40"')}${field('倉庫名稱','name','','text','required maxlength="100"')}</div></form>`,formFooter());return;}
 if(a==='password-form'){modal('變更我的密碼',`<form id="modal-form" data-form="password"><div class="form-grid">${field('目前密碼','old_password','','password','required autocomplete="current-password"',true)}${field('新密碼','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"',true)}</div><p class="hint">儲存後會登出所有連線，請以新密碼重新登入。</p></form>`,formFooter('變更並重新登入'));return;}
 if(a==='loan-return'){const l=S.data.loans.find(x=>x.id===Number(id));S.editEntity=l;modal('借用歸還',`<form id="modal-form" data-form="loan-return"><p>${E(l.no)} · ${E(l.product_name)} · 尚未歸還 ${Q(l.qty-l.returned_qty)} ${E(l.unit)}</p><div class="form-grid">${field('本次歸還數量','qty',inputQty(l.qty-l.returned_qty),'number',`min="0.001" max="${inputQty(l.qty-l.returned_qty)}" step="0.001" required`)}</div></form>`,formFooter('確認歸還過帳'));return;}
 if(a==='reject-doc'||a==='cancel-doc'){const d=S.docDetail;S.actionDoc=d;S.actionType=a==='reject-doc'?'reject':'cancel';modal(a==='reject-doc'?'退回單據':'取消單據',`<form id="modal-form" data-form="doc-reason"><p>${E(d.no)} · ${E(d.partner_name)}</p><div class="form-grid">${textarea('原因（必填）','reason','')}</div><p class="hint">${a==='cancel-doc'?'已核准訂單將釋放預留庫存。已有交貨紀錄的單據須使用退貨流程。':'退回後可修改草稿並重新送審。'}</p></form>`,formFooter('確認'+(a==='reject-doc'?'退回':'取消')));return;}
 if(a.startsWith('workflow-')&&await workflowAction(a,id))return;
 if(a.startsWith('v3-')&&await opsAction(a,id))return;
 if(a.startsWith('v2-')){if(a==='v2-use-address'){const x=S.data.addresses.find(x=>x.id===Number(id));if(x)$('#f-shipping_address').value=x.address;return;}if(await v2Action(a,id))return;}
 if(a==='help'){modal('開始使用成祥 ERP',`<div class="checklist"><span>01　建立客戶、供應商、商品與倉庫，或由 CSV 匯入。</span><span>02　業務查詢歷史交易與庫存，建立報價或訂單草稿。</span><span>03　開啟「黃單／PDF」，可列印 A4 或 A5 橫式。</span><span>04　送出審核 → 主管核准；訂單此時預留庫存。</span><span>05　倉管依實際數量分批出貨／進貨，自動立帳。</span><span>06　財務收付款沖帳，查詢傳票與試算表。</span><span>07　定期下載備份，並執行資料一致性檢查。</span></div><p class="hint">此為單一公司核心試行版；尚未接入實際公司舊資料與電子發票。示範資料庫與正式資料庫分離。伺服器預設僅開放本機，跨裝置使用需部署網路與 HTTPS。</p>`,btn('開始作業','close','', 'primary'));return;}
 if(a==='quick'){if(id==='order'||id==='quote')newDoc(id);else if(id==='stock')navigate('inventory');else partnerForm('');return;}
 if(a==='export'){const k=id==='stocks'?'stocks':id;window.location.href='/api/export?kind='+encodeURIComponent(k);return;}
 if(a==='backup'){window.location.href='/api/backup';return;}
 if(a==='import-template'){const k=$('#f-kind').value;downloadText(k+'-template.csv',{products:'sku,name,spec,category,unit,barcode,price,cost,safety_qty\r\nSAMPLE-01,範例商品,規格,類別,個,,100.00,60.00,10\r\n',partners:'code,name,kind,contact,phone,email,tax_id,address,payment_days,credit_limit\r\nC-SAMPLE,範例客戶,customer,聯絡人,,,,,30,50000\r\n',opening_stock:'sku,warehouse_code,qty,unit_cost\r\nSAMPLE-01,WH01,20,60.00\r\n'}[k]);return;}
 el.disabled=true;
 if(a==='refresh'){await refresh();toast('資料已更新');}
 else if(a==='logout'){await api('/api/logout',{});S.data=null;closeModal();await init();}
 else if(a==='demo-enter'){const r=await api('/api/demo',{});S.csrf=r.csrf;await refresh();}
 else if(a==='doc-action'){const d=S.docDetail;const r=await api(`/api/documents/${d.id}/${id}`,{version:d.version});await refresh();await showDoc(r.id);toast(id==='convert'?'報價已轉為訂單草稿':'單據已更新');}
 else if(a==='complete-work'){await api(`/api/work-orders/${id}/complete`,{});await refresh();toast('組裝完成，材料與成品庫存已更新');}
 else if(a==='count-post'){const c=S.countDetail,saved=await api(`/api/inventory-counts/${c.id}/save`,{version:c.version,notes:$('#f-notes').value,lines:$$('[data-count-line]').map(el=>({line_id:Number(el.dataset.countLine),actual_qty:el.value}))});S.countDetail=saved;await api(`/api/inventory-counts/${c.id}/post`,{version:saved.version});closeModal();await refresh();toast('盤點差異已過帳，庫存與會計已更新');}
 else if(a==='integrity'){const r=await api('/api/integrity');$('#integrity-result').innerHTML=`<div class="${r.ok?'checklist':'alert error'}" style="margin-top:20px">${r.ok?r.checks.map(x=>`<span>✓ ${E(x)}：通過</span>`).join(''):E(JSON.stringify(r.problems))}</div>`;}
 else if(a==='journal-detail'){const j=await api('/api/journals/'+id);modal(j.no,`<p>${E(j.date)} · ${E(j.memo)} · ${E(j.reference)}</p>${table(['科目','名稱','借方','貸方'],j.lines.map(l=>`<tr><td class="mono">${E(l.account)}</td><td>${E(l.name)}</td><td>${money(l.debit)}</td><td>${money(l.credit)}</td></tr>`))}`,btn('關閉','close'));}
 else if(a==='import-commit'){const r=await api(`/api/imports/${S.importId}/commit`,{});S.importId=null;await refresh();toast(`已匯入 ${r.count} 筆資料`);}
 }catch(e){if($('#form-error'))$('#form-error').textContent=e.message;else toast(e.message,true);}finally{if(el.isConnected)el.disabled=false;}
});

document.addEventListener('submit',async ev=>{const form=ev.target;if(!form.dataset.form)return;ev.preventDefault();const kind=form.dataset.form,b=Object.fromEntries(new FormData(form));const submit=document.querySelector(`[form="${form.id}"][type="submit"]`)||form.querySelector('[type="submit"]');if(submit)submit.disabled=true;const error=$('#form-error')||$('#page-error')||$('#login-error');if(error)error.textContent='';try{
 let r;
 if(kind.startsWith('workflow-')){await workflowSubmit(kind,b);return;}
 if(kind==='v2'){r=await v2Submit(b);closeModal();await refresh();toast(r?.no?'作業完成 · '+r.no:'資料已儲存');return;}
 if(kind==='login'||kind==='setup'){r=await api('/api/'+kind,b);S.csrf=r.csrf;await refresh();return;}
 if(kind==='document'){collectDocLines();const x=S.docDraft;r=await api(x.direct?'/api/direct-trades':'/api/documents',{...b,id:x.id,version:x.version,kind:x.kind,tax_bp:Number(b.tax_bp),valid_until:x.kind==='quote'?b.due_date:'',lines:x.lines});const docId=x.direct?r.document.id:r.id;closeModal();await refresh();await showDoc(docId);toast(x.direct?'直接出入庫與立帳完成':'草稿已儲存，可列印黃單或送審');return;}
 if(kind==='ops-rebuild-preview'){S.rebuildPlan=await api('/api/rebuilds/preview?'+new URLSearchParams(b));render();return;}
 if(kind==='ops-rebuild-commit'){const r=await api('/api/rebuilds/commit',{...b,kind:S.rebuildPlan.kind,token:S.rebuildPlan.token});S.rebuildPlan=null;await refresh();toast('已備份並重建 '+r.count+' 筆 · '+r.no);return;}
 if(kind==='ops-report'){S.opsReport=await api('/api/reports/trading?'+new URLSearchParams(b));render();return;}
 if(kind==='ops'){r=await opsSubmit(b);if(r?.preview)return;const pickId=S.opsEntity.type==='pick'?r.id:null;closeModal();await refresh();if(pickId)await opsPick(pickId);toast(r?.no?'作業完成 · '+r.no:'資料已儲存');return;}
 if(kind==='ops-scan'){const id=S.opsPick.id;await api('/api/picks/'+id+'/scan',b);await refresh();await opsPick(id);toast('掃碼比對已登錄');return;}
 if(kind==='partner')r=await api('/api/partners',{...b,id:S.editEntity.id,version:S.editEntity.version});
 else if(kind==='product')r=await api('/api/products',{...b,id:S.editEntity.id,version:S.editEntity.version});
 else if(kind==='stock')r=await api(S.stockKind==='transfer'?'/api/transfers':'/api/adjustments',b);
 else if(kind==='warehouse')r=await api('/api/warehouses',b);
 else if(kind==='count-create'){r=await api('/api/inventory-counts',b);closeModal();await refresh();await countOpen(r.id);toast('盤點快照已建立');return;}
 else if(kind==='count-save'){const c=S.countDetail;r=await api(`/api/inventory-counts/${c.id}/save`,{...b,version:c.version,lines:$$('[data-count-line]').map(el=>({line_id:Number(el.dataset.countLine),actual_qty:el.value}))});closeModal();await refresh();await countOpen(r.id);toast('實盤數量已儲存，尚未變更庫存');return;}
 else if(kind==='count-cancel')r=await api(`/api/inventory-counts/${S.countToCancel.id}/cancel`,{...b,version:S.countToCancel.version});
 else if(kind==='order-purchase'){r=await api(`/api/documents/${S.orderPurchase.id}/purchase`,{...b,lines:$$('[data-po-line]').map(tr=>({product_id:Number(tr.dataset.poLine),qty:tr.querySelector('[name="po_qty"]').value,price:tr.querySelector('[name="po_price"]').value})).filter(l=>Number(l.qty)>0)});closeModal();await refresh();await showDoc(r.id);toast('已建立連動採購草稿');return;}
 else if(kind==='price')r=await api('/api/prices',{...b,partner_id:S.pricePartner});
 else if(kind==='fulfil'){r=await api(`/api/documents/${S.fulfilDoc.id}/fulfil`,{lines:$$('[data-fulfil-line]').map(el=>({line_id:Number(el.dataset.fulfilLine),qty:el.value}))});}
 else if(kind==='payment')r=await api('/api/payments',{...b,open_item_id:S.editEntity.id});
 else if(kind==='return')r=await api('/api/returns',{...b,allow_credit:true,fulfilment_id:S.returnSource.id,lines:$$('[data-return-line]').map(el=>({line_id:Number(el.dataset.returnLine),qty:el.value}))});
 else if(kind==='activity')r=await api('/api/activities',b);
 else if(kind==='work')r=await api('/api/work-orders',b);
 else if(kind==='bom'){collectBom();r=await api('/api/boms',{...b,version:S.editEntity.version,lines:S.bomLines});}
 else if(kind==='loan')r=await api('/api/loans',b);
 else if(kind==='loan-return')r=await api(`/api/loans/${S.editEntity.id}/return`,b);
 else if(kind==='user'){r=await api('/api/users',{...b,id:S.editEntity.id,active:b.active==='1'});if(S.editEntity.id===S.data.user.id){S.data=null;closeModal();await init();return;}}
 else if(kind==='journal')r=await api('/api/journals',{...b,lines:$$('#journal-lines tbody tr').map(tr=>Object.fromEntries([...tr.querySelectorAll('input,select')].map(el=>[el.name,el.value])))});
 else if(kind==='password'){await api('/api/password',b);S.data=null;closeModal();await init();toast('密碼已變更，請重新登入');return;}
 else if(kind==='doc-reason'){r=await api(`/api/documents/${S.actionDoc.id}/${S.actionType}`,{version:S.actionDoc.version,reason:b.reason});}
 else if(kind==='company'){await api('/api/settings',b);await refresh();toast('公司設定已儲存');return;}
 else if(kind==='import-preview'){const file=$('#import-file').files[0];if(file.size>2*1024*1024)throw Error('CSV 檔案請小於 2MB');const text=await file.text(),rows=parseCSV(text);r=await api('/api/imports/preview',{kind:b.kind,rows});S.importId=r.id;$('#import-result').innerHTML=`<div class="section-title">預覽結果：共 ${r.count} 筆，${r.errors.length} 個錯誤</div>${r.errors.length?`<div class="alert error">${r.errors.slice(0,30).map(e=>'第 '+e.row+' 列：'+E(e.message)).join('<br>')}</div>`:`<div class="alert">檢核通過。確認匯入後，整批資料會在同一筆交易寫入。</div>${btn('確認匯入 '+r.count+' 筆','import-commit','','primary','check')}`}`;return;}
 closeModal();await refresh();toast(r?.no?'作業完成 · '+r.no:'資料已儲存');
 }catch(e){if(error?.isConnected)error.textContent=e.message;else toast(e.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});

let filterTimer;document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.filter==='text'){clearTimeout(filterTimer);const start=el.selectionStart;filterTimer=setTimeout(()=>{S.filter=el.value;render();const fresh=$('#list-search');fresh?.focus();fresh?.setSelectionRange(start,start);},220);}if(el.closest('#doc-lines')&&el.tagName==='INPUT'){if(el.name==='price')S.priceRevision=(S.priceRevision||0)+1;updateDocTotals();}if(el.id==='f-header_discount')updateDocTotals();if(el.id==='f-tax_bp'&&S.docDraft)updateDocTotals();});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.dataset.filter==='status'){S.statusFilter=el.value;render();}if(el.dataset.filter==='warehouse'){S.warehouseFilter=el.value;render();}try{await opsDocumentChange(el);}catch(e){toast(e.message,true);}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&$('#modal-root').innerHTML){closeModal();return;}if(ev.key==='Tab'&&$('#modal-root').innerHTML){const focusable=$$('#modal-root button:not(:disabled),#modal-root input,#modal-root select,#modal-root textarea,#modal-root a[href]');const first=focusable[0],last=focusable.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}
 if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();$('#global-search')?.focus();}if(ev.key==='Enter'&&ev.target.id==='global-search'){ev.preventDefault();const term=ev.target.value.toLowerCase(),d=S.data;if(!term)return;const docs=d.documents.filter(x=>(x.no+' '+x.partner_name).toLowerCase().includes(term)),products=d.products.filter(x=>(x.sku+' '+x.name+' '+x.barcode).toLowerCase().includes(term)),partners=d.partners.filter(x=>(x.code+' '+x.name+' '+x.phone).toLowerCase().includes(term));modal('搜尋結果',`<div class="section-title">單據 ${docs.length} 筆</div>${table(['單號','往來對象','類型'],docs.slice(0,20).map(x=>`<tr data-open="document" data-id="${x.id}"><td class="mono">${E(x.no)}</td><td>${E(x.partner_name)}</td><td>${E(kindNames[x.kind])}</td></tr>`))}<div class="section-title">商品 ${products.length} 筆</div><div class="actions">${products.slice(0,20).map(p=>btn(p.sku+' '+p.name,'product-info',p.id,'small')).join('')}</div><div class="section-title">客戶／廠商 ${partners.length} 筆</div><div class="actions">${partners.slice(0,20).map(p=>btn(p.name,'partner-info',p.id,'small')).join('')}</div>`,btn('關閉','close'),true);}});

async function init(){try{S.companies=await (await fetch('/api/companies')).json();if(!S.companies.some(c=>c.slug===S.company)){S.company='default';sessionStorage.setItem('cheng-company','default');}const st=await api('/api/status');S.demo=st.demo;try{const session=await api('/api/session');S.csrf=session.csrf;await refresh();return;}catch{}
const setup=!st.initialized;$('#app').innerHTML=`<main class="login-page"><section class="login-story"><div class="brand"><img src="/favicon.svg" alt=""><span>成祥 ERP<small>CHENG WORKSPACE</small></span></div><div class="login-copy"><div class="tagline">A CLEARER WAY TO WORK</div><h1>讓營運井然有序，<br>讓生意穩健向前。</h1><p>從第一張報價，到每一次交貨。<br>把業務、採購、庫存與帳款連在一起，<br>留更多時間，做好真正重要的事。</p></div><div class="login-art"></div><div class="login-version">CHENG ERP · 2026 · BUILT FOR YOUR BUSINESS</div></section><section class="login-form-area"><div class="login-form">${companyLoginSelector()}<div class="eyebrow">${setup?'CREATE YOUR WORKSPACE':'WELCOME BACK'}</div><h2>${setup?'建立公司的工作空間':'歡迎回到工作空間'}</h2><p>${setup?'第一次使用，請設定公司與管理員。':'登入帳號，開始今天的營運工作。'}</p>${st.demo?`<div class="alert">獨立示範環境 · 所有資料均為虛構，可自由體驗功能。</div>${btn('進入示範工作空間','demo-enter','','primary','arrow')}`:`<form id="login-form" data-form="${setup?'setup':'login'}">${setup?field('公司名稱','company','成祥','text','required maxlength="100"')+field('管理員姓名','name','','text','required maxlength="80"'):''}${field('帳號','username','','text',`required ${setup?'minlength="3" maxlength="50"':''} autocomplete="username"`)}${field(setup?'設定密碼（至少 12 字）':'密碼','password','','password',`required ${setup?'minlength="12" maxlength="128"':''} autocomplete="${setup?'new-password':'current-password'}"`)}<p class="form-error" id="login-error" role="alert"></p><button class="btn primary" type="submit">${setup?'建立工作空間':'登入工作空間'} ${I('arrow')}</button></form>`}<p class="hint">${setup?'正常啟動不含示範資料。管理員可建立各部門帳號，並匯入公司資料。':'資料儲存在公司伺服器資料庫。請使用管理員提供的帳號登入。'}<br>多公司核心試行版 · v0.4.0</p></div></section></main>`;
}catch(e){$('#app').innerHTML=`<div class="boot"><h2>暫時無法連線</h2><p>${E(e.message)}</p><button data-action="refresh" class="btn">重新整理</button></div>`;}}
init();
